/* ================================================================
   Camzy — Iran provinces/cities loader.
   - Ships with the full 31-province data embedded so the Add-Address
     modal works without a network request (static/offline/file://).
   - Also refreshes from assets/data/iran-cities.json when possible
     (keeps the JSON authoritative and up to date).
   - Exposes window.IranCities and window.IranCitiesLoader.
   ================================================================ */
(function () {
  'use strict';

  /* Embedded copy of assets/data/iran-cities.json — always available,
     so the Province/City dropdowns are populated even when fetch()
     is blocked (file://), offline, or a stale service-worker cache
     serves a bad body. */
  var FALLBACK = [{"name":"آذربایجان شرقی","cities":["تبریز","مراغه","مرند","اهر","میانه","بناب","شبستر","سراب","کلیبر","هشترود","آذرشهر","جلفا","ورزقان"]},{"name":"آذربایجان غربی","cities":["ارومیه","خوی","مهاباد","بوکان","میاندوآب","سلماس","پیرانشهر","نقده","تکاب","سردشت","شاهین‌دژ","اشنویه","چایپاره"]},{"name":"اردبیل","cities":["اردبیل","پارس‌آباد","مشگین‌شهر","خلخال","گرمی","بیله‌سوار","نمین","نیر","سرعین","کوثر"]},{"name":"اصفهان","cities":["اصفهان","کاشان","خمینی‌شهر","نجف‌آباد","شاهین‌شهر","شهرضا","فلاورجان","مبارکه","نائین","سمیرم","گلپایگان","لنجان","نطنز","آران و بیدگل"]},{"name":"البرز","cities":["کرج","فردیس","کمال‌شهر","نظرآباد","محمدشهر","هشتگرد","مشکین‌دشت","اشتهارد","طالقان","چهارباغ"]},{"name":"ایلام","cities":["ایلام","دهلران","ایوان","آبدانان","دره‌شهر","مهران","چرداول","ملکشاهی","بدره","سیروان"]},{"name":"بوشهر","cities":["بوشهر","برازجان","بندر کنگان","بندر گناوه","خورموج","عسلویه","جم","دیر","دشتی","تنگستان"]},{"name":"تهران","cities":["تهران","اسلامشهر","شهریار","قدس","ملارد","ری","ورامین","پاکدشت","رباط‌کریم","دماوند","فیروزکوه","پردیس","بهارستان","قرچک","پیشوا"]},{"name":"چهارمحال و بختیاری","cities":["شهرکرد","بروجن","لردگان","فارسان","فرخ‌شهر","هفشجان","اردل","سامان","کیار","کوهرنگ"]},{"name":"خراسان جنوبی","cities":["بیرجند","قائن","فردوس","طبس","نهبندان","سربیشه","سرایان","بشرویه","درمیان","زیرکوه"]},{"name":"خراسان رضوی","cities":["مشهد","نیشابور","سبزوار","تربت‌حیدریه","کاشمر","قوچان","تربت‌جام","تایباد","چناران","سرخس","گناباد","خواف","بردسکن"]},{"name":"خراسان شمالی","cities":["بجنورد","شیروان","اسفراین","آشخانه","فاروج","جاجرم","گرمه","راز و جرگلان"]},{"name":"خوزستان","cities":["اهواز","آبادان","خرمشهر","دزفول","ماهشهر","اندیمشک","ایذه","بهبهان","شوشتر","شوش","مسجدسلیمان","رامهرمز","بندر امام خمینی"]},{"name":"زنجان","cities":["زنجان","ابهر","خرمدره","قیدار","ماهنشان","طارم","سلطانیه","ایجرود"]},{"name":"سمنان","cities":["سمنان","شاهرود","دامغان","گرمسار","مهدی‌شهر","سرخه","آرادان","میامی"]},{"name":"سیستان و بلوچستان","cities":["زاهدان","زابل","ایرانشهر","چابهار","سراوان","خاش","کنارک","نیک‌شهر","میرجاوه","زهک"]},{"name":"فارس","cities":["شیراز","مرودشت","جهرم","فسا","کازرون","لار","داراب","فیروزآباد","لامرد","ممسنی","نی‌ریز","اقلید","سپیدان","استهبان"]},{"name":"قزوین","cities":["قزوین","تاکستان","الوند","آبیک","بوئین‌زهرا","آوج"]},{"name":"قم","cities":["قم","قنوات","جعفریه","کهک","دستجرد"]},{"name":"کردستان","cities":["سنندج","سقز","مریوان","بانه","قروه","کامیاران","بیجار","دیواندره","دهگلان","سروآباد"]},{"name":"کرمان","cities":["کرمان","سیرجان","رفسنجان","جیرفت","بم","زرند","شهربابک","کهنوج","بافت","بردسیر","راور","عنبرآباد"]},{"name":"کرمانشاه","cities":["کرمانشاه","اسلام‌آباد غرب","هرسین","کنگاور","سنقر","جوانرود","صحنه","پاوه","گیلان‌غرب","سرپل ذهاب"]},{"name":"کهگیلویه و بویراحمد","cities":["یاسوج","گچساران","دهدشت","لیکک","سی‌سخت","چرام","باشت","لنده"]},{"name":"گلستان","cities":["گرگان","گنبد کاووس","علی‌آباد","بندر ترکمن","آق‌قلا","کردکوی","کلاله","مینودشت","گمیشان","رامیان"]},{"name":"گیلان","cities":["رشت","بندر انزلی","لاهیجان","لنگرود","آستارا","تالش","رودسر","صومعه‌سرا","فومن","آستانه اشرفیه","رضوانشهر","ماسال"]},{"name":"لرستان","cities":["خرم‌آباد","بروجرد","دورود","کوهدشت","الیگودرز","نورآباد","ازنا","پلدختر","الشتر"]},{"name":"مازندران","cities":["ساری","بابل","آمل","قائم‌شهر","بهشهر","تنکابن","چالوس","نکا","نوشهر","بابلسر","جویبار","محمودآباد","رامسر","نور"]},{"name":"مرکزی","cities":["اراک","ساوه","خمین","محلات","دلیجان","شازند","تفرش","آشتیان","کمیجان","زرندیه"]},{"name":"هرمزگان","cities":["بندرعباس","میناب","بندر لنگه","قشم","کیش","رودان","حاجی‌آباد","بندر جاسک","پارسیان","خمیر"]},{"name":"همدان","cities":["همدان","ملایر","نهاوند","اسدآباد","بهار","تویسرکان","کبودرآهنگ","رزن","فامنین"]},{"name":"یزد","cities":["یزد","میبد","اردکان","مهریز","بافق","ابرکوه","تفت","اشکذر","خاتم","بهاباد"]}];
  var cache = null;
  var pending = null;

  function isUsable(d) { return Array.isArray(d) && d.length > 0; }

  function sync(d) {
    cache = d;
    window.IranCities = d;
    if (typeof AppData !== 'undefined' && AppData) { try { AppData.provinces = d; } catch (e) {} }
  }

  function flush(d) {
    sync(d);
    var queue = pending || [];
    pending = null;
    queue.forEach(function (fn) { try { fn(d); } catch (e) {} });
  }

  function load(cb) {
    if (cache) { if (cb) cb(cache); return; }
    if (pending) { if (cb) pending.push(cb); return; }
    pending = cb ? [cb] : [];
    fetch('assets/data/iran-cities.json')
      .then(function (r) {
        if (!r.ok) throw new Error('HTTP ' + r.status);
        return r.json();
      })
      .then(function (data) {
        flush(isUsable(data) ? data : FALLBACK);
      })
      .catch(function () {
        flush(FALLBACK);
      });
  }

  /* Publish synchronously so the modal never renders an empty list. */
  window.IranCities = FALLBACK;
  if (typeof AppData !== 'undefined' && AppData) { try { AppData.provinces = FALLBACK; } catch (e) {} }

  window.IranCitiesLoader = {
    load: load,
    get: function () { return cache || FALLBACK; }
  };

  load(function () {});
})();
